// @generated by:gauntlet run:godseye-local-backend
import { randomUUID } from "node:crypto";
import { afterEach, describe, expect, it } from "vitest";
import { type BackendFixture, backendFixture } from "./backend-fixture.js";
import { openEvents, readSseFrame } from "./backend-stream-fixture.js";

describe("bounded realtime retention and connection capacity", () => {
  let fixture: BackendFixture | undefined;
  afterEach(async () => fixture?.close());
  async function setup(
    limits: { eventRetention?: number; streamConnections?: number; streamLifetimeMs?: number } = {},
  ) {
    fixture = await backendFixture({ limits: { streamPollMs: 10, ...limits } });
    const user = await fixture.register();
    return {
      fixture,
      cookie: user.cookie,
      publish: (version: number) =>
        fixture?.runtime.publishEvent({
          userId: user.user.id,
          type: "document.updated",
          payload: { version },
          idempotencyKey: randomUUID(),
        }),
    };
  }

  it("T-AC-58 signals refetch and closes when the cursor predates retained events", async () => {
    const { fixture, cookie, publish } = await setup({ eventRetention: 1 });
    await publish(1);
    const initial = await openEvents(fixture, cookie);
    const cursor = (await readSseFrame(initial.reader, "domain")).id;
    await initial.reader.cancel();
    await publish(2);
    await publish(3);
    const resumed = await openEvents(fixture, cookie, cursor);
    expect((await readSseFrame(resumed.reader, "refetch")).data).toEqual({ reason: "cursor_gap" });
    expect((await resumed.reader.read()).done).toBe(true);
  });

  it("T-AC-59 releases an unread stream's finite slot when its lifetime expires", async () => {
    const { fixture, cookie } = await setup({ streamConnections: 1, streamLifetimeMs: 100 });
    const unread = await fixture.request("/events", { headers: { cookie } });
    expect(unread.status).toBe(200);
    expect((await fixture.request("/events", { headers: { cookie } })).status).toBe(429);
    await new Promise((resolve) => setTimeout(resolve, 150));
    const replacement = await fixture.request("/events", { headers: { cookie } });
    expect(replacement.status).toBe(200);
    await unread.body?.cancel();
    await replacement.body?.cancel();
  });

  it("T-AC-59 releases a request-aborted unread stream without waiting for a consumer pull", async () => {
    const { fixture, cookie } = await setup({ streamConnections: 1 });
    const abort = new AbortController();
    const unread = await fixture.request("/events", { headers: { cookie }, signal: abort.signal });
    expect(unread.status).toBe(200);
    abort.abort();
    const replacement = await fixture.request("/events", { headers: { cookie } });
    expect(replacement.status).toBe(200);
    await unread.body?.cancel();
    await replacement.body?.cancel();
  });

  it("T-AC-59 cancellation immediately frees the single stream slot", async () => {
    const { fixture, cookie } = await setup({ streamConnections: 1 });
    const stream = await openEvents(fixture, cookie);
    await stream.reader.cancel();
    const replacement = await fixture.request("/events", { headers: { cookie } });
    expect(replacement.status).toBe(200);
    await replacement.body?.cancel();
  });

  it("T-AC-59 keeps a non-reading subscriber from consuming the durable event history", async () => {
    const { fixture, cookie, publish } = await setup({ eventRetention: 2 });
    const unread = await fixture.request("/events", { headers: { cookie } });
    for (let i = 1; i <= 5; i++) await publish(i);
    expect(unread.body).not.toBeNull();
    const reader = unread.body?.getReader();
    if (!reader) throw new Error("Missing slow stream");
    const frame = await readSseFrame(reader, "domain");
    expect(frame.data).toMatchObject({ payload: { version: 4 } });
    await reader.cancel();
  });
});
